/**
 * The signature mark, stored as a 128x128 1-bit bitmap.
 *
 * Keeping it here rather than loading /profile_*.png means the hero canvas
 * needs no network request, no image decode and no raster upscaling - the
 * points are scaled as coordinates, so the mark stays sharp at any size.
 */
const MARK = ''

const GRID = 128

let cache: SignatureMark | null = null

export interface SignatureMark {
  /** Points normalised into a centred unit square. */
  points: Array<[number, number]>
  /** Width of the mark in grid cells, used to derive dot spacing. */
  span: number
}

export function signatureMark(): SignatureMark {
  if (cache) {
    return cache
  }

  const raw = atob(MARK)
  const cells: Array<[number, number]> = []

  let minX = GRID
  let minY = GRID
  let maxX = 0
  let maxY = 0

  for (let y = 0; y < GRID; y++) {
    for (let x = 0; x < GRID; x++) {
      const i = y * GRID + x

      if (!(raw.charCodeAt(i >> 3) & (1 << (7 - (i & 7))))) {
        continue
      }

      cells.push([x, y])
      minX = Math.min(minX, x)
      minY = Math.min(minY, y)
      maxX = Math.max(maxX, x)
      maxY = Math.max(maxY, y)
    }
  }

  const width = maxX - minX
  const height = maxY - minY
  const span = Math.max(width, height)

  cache = {
    span,
    points: cells.map(([x, y]) => [
      (x - minX - width / 2) / span + 0.5,
      (y - minY - height / 2) / span + 0.5,
    ]),
  }

  return cache
}
